   if(c&&!isManual(p)){
     if(N(p.lat)!==N(c.lat)||N(p.lng)!==N(c.lng)||p.dataVersion!==VERSION)changed=true;
     p.lat=c.lat;p.lng=c.lng;p.coordinateAccuracy=c.coordinateAccuracy;p.coordinateSource=c.coordinateSource;p.geocodeMethod=c.geocodeMethod;p.inferredLocation=!!c.inferredLocation;p.verification='needs_review';
   }
