 UI.route=route;var all=allFor(route),rows=filtered(route),countries=distinct(rows,'country'),cities=distinct(all.filter(function(p){return !(UI.countries||[]).length||(UI.countries||[]).indexOf(p.country)>=0;}),'city'),cats=distinct(all,'category'),years=distinct(all,'openingYear').sort(function(a,b){return N(b)-N(a);});
 var gba=rows.reduce(function(a,p){return a+N(p.gba);},0),gla=rows.reduce(function(a,p){return a+N(p.gla);},0),verified=rows.filter(function(p){return p.verification==='verified';}).length;
