 var kpis='<section class="case493-kpis"><div><b>'+rows.length+'</b><span>проектов</span></div><div><b>'+F(gba)+'</b><span>Σ GBA, м²</span></div><div><b>'+F(gla)+'</b><span>Σ GLA, м²</span></div><div><b>'+countries.length+'</b><span>стран</span></div><div><b>'+verified+'</b><span>точных точек</span></div></section>';
 var controls='<div class="case493-map-tools"><select onchange="case493Set(\'provider\',this.value)"><option value="auto"'+(UI.provider==='auto'?' selected':'')+'>Карта: автоматически</option><option value="yandex"'+(UI.provider==='yandex'?' selected':'')+'>Яндекс Карты</option><option value="osm"'+(UI.provider==='osm'?' selected':'')+'>OpenStreetMap</option></select><select onchange="case493Set(\'colorMode\',this.value)"><option value="country"'+(UI.colorMode==='country'?' selected':'')+'>Цвет по стране</option><option value="category"'+(UI.colorMode==='category'?' selected':'')+'>Цвет по категории</option></select><label><input type="checkbox" '+(UI.cluster?'checked':'')+' onchange="case493Set(\'cluster\',this.checked)"> Кластеры</label><label><input type="checkbox" '+(UI.labels?'checked':'')+' onchange="case493Set(\'labels\',this.checked)"> Подписи</label><button onclick="case493Fit()" title="Показать все">⌗</button></div>';
 var list='<aside class="case493-list"><div class="case493-list-head"><div><b>'+rows.length+' проектов</b><span>Нажмите для подробностей</span></div><select onchange="case493Set(\'sort\',this.value)"><option value="gla_desc"'+(UI.sort==='gla_desc'?' selected':'')+'>По GLA</option><option value="name"'+(UI.sort==='name'?' selected':'')+'>По названию</option><option value="year_desc"'+(UI.sort==='year_desc'?' selected':'')+'>По году</option></select></div><div class="case493-list-scroll">'+(rows.length?rows.map(function(p){return '<button class="case493-list-item'+(p.id===UI.selectedId?' active':'')+'" data-pid="'+E(p.id)+'" onclick="case493Focus(\''+E(p.id)+'\')"><i style="background:'+E(color(p))+'"></i><span><b>'+E(p.name)+'</b><small>'+E(p.city)+' · '+E(p.country)+' · '+E(p.category)+'</small></span><em>'+F(p.gla)+'</em></button>';}).join(''):'<div class="case493-no-results">По выбранным фильтрам проектов нет.</div>')+'</div></aside>';
 var legendKeys=UI.colorMode==='category'?distinct(rows,'category'):distinct(rows,'country');var legend='<div class="case493-legend"><b>'+(UI.colorMode==='category'?'Категория':'Страна')+'</b>'+legendKeys.slice(0,12).map(function(x){var tmp=UI.colorMode==='category'?{category:x,country:''}:{country:x,category:''};return '<span><i style="background:'+E(color(tmp))+'"></i>'+E(x)+'</span>';}).join('')+'</div>';
 var map='<section class="case493-map-shell">'+controls+'<div id="case493Map" class="case493-map"><div class="case493-map-loading"><b>Подготавливаем карту портфеля</b><span>Фильтры и список уже доступны.</span></div></div>'+legend+'<aside id="case493Detail" class="case493-detail'+(selected?' open':'')+'">'+projectDetail(selected)+'</aside></section>';
 var warning='<div class="case493-warning"><b>Точность данных</b><span>91 точка импортирована из предоставленной карты как геокодирование уровня города. Они не считаются точным адресом до ручного подтверждения. Четыре проекта без координат в исходном наборе сохранены как предположительные городские точки.</span><button onclick="case493NeedsReview()">Показать требующие проверки</button></div>';
