window.case493Select=function(id,focus){UI.selectedId=id||'';document.querySelectorAll('.case493-list-item').forEach(function(x){x.classList.toggle('active',x.getAttribute('data-pid')===id);});var d=document.getElementById('case493Detail'),p=CASE_PORTFOLIO_PROJECTS.find(function(x){return x.id===id;});if(d){d.innerHTML=projectDetail(p);d.classList.toggle('open',!!p);}if(focus!==false){if(MAPRT.provider==='yandex')focusYandex(id);else if(MAPRT.provider==='leaflet')focusLeaflet(id);}};
