window.case493OpenGeo=function(id){try{if(typeof go==='function')go('geoanalytics');setTimeout(function(){if(typeof window.geoV42Project==='function')window.geoV42Project(id);var s=document.getElementById('geoProject');if(s){s.value=id;s.dispatchEvent(new Event('change',{bubbles:true}));}},240);}catch(e){}};
window.case493CoordinateEdit=function(id){var p=CASE_PORTFOLIO_PROJECTS.find(function(x){return x.id===id;});if(!p||!canEdit())return;var w=document.createElement('div');w.className='case493-modal-wrap';w.innerHTML='<div class="case493-modal"><header><div><small>Проверка координат</small><h2>'+E(p.name)+'</h2></div><button onclick="this.closest(\'.case493-modal-wrap\').remove()">×</button></header><div class="case493-modal-body"><label>Широта<input id="c493lat" type="number" min="-90" max="90" step="0.000001" value="'+E(p.lat)+'"></label><label>Долгота<input id="c493lng" type="number" min="-180" max="180" step="0.000001" value="'+E(p.lng)+'"></label><label class="full">Источник / адрес / ссылка<textarea id="c493src" placeholder="Укажите, где проверена точка">'+E(p.coordinateSource||'')+'</textarea></label><label class="case493-check full"><input id="c493verified" type="checkbox" '+(p.verification==='verified'?'checked':'')+'> Подтверждаю точную локацию объекта</label><p class="full">Исходная и подтверждённая история сохраняется в карточке проекта. Подтверждённые вручную координаты не перезаписываются будущими импортами.</p></div><footer><button class="btn ghost" onclick="this.closest(\'.case493-modal-wrap\').remove()">Отмена</button><button class="btn" onclick="case493CoordinateSave(\''+E(id)+'\')">Сохранить</button></footer></div>';document.body.appendChild(w);};
window.case493CoordinateSave=function(id){var p=CASE_PORTFOLIO_PROJECTS.find(function(x){return x.id===id;});if(!p)return;var lat=N(document.getElementById('c493lat').value),lng=N(document.getElementById('c493lng').value),verified=document.getElementById('c493verified').checked,src=document.getElementById('c493src').value.trim();if(lat<-90||lat>90||lng<-180||lng>180){alert('Координаты вне допустимого диапазона.');return;}p.coordinateHistory=Array.isArray(p.coordinateHistory)?p.coordinateHistory:[];p.coordinateHistory.push({lat:p.lat,lng:p.lng,accuracy:p.coordinateAccuracy,source:p.coordinateSource||'',changedAt:new Date().toISOString()});p.lat=lat;p.lng=lng;p.verification=verified?'verified':'needs_review';p.coordinateAccuracy=verified?'exact_manual':'manual_unverified';p.coordinateSource=src||'Ручная корректировка';p.geocodeMethod='manual';p.verifiedAt=verified?new Date().toISOString():'';try{p.verifiedBy=(S.user&&S.user.name)||'';}catch(e){}persistQuiet();try{if(typeof audit==='function')audit('Портфель CASE: координаты изменены',p.name);}catch(e){}var m=document.querySelector('.case493-modal-wrap');if(m)m.remove();redraw();};
function safeCsv(v){var s=Array.isArray(v)?v.join(' | '):String(v==null?'':v);if(/^[=+\-@]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}
function saveFile(name,content,type){if(typeof download==='function'){download(name,content,type);return;}var b=new Blob([content],{type:type}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(function(){URL.revokeObjectURL(a.href);},500);}
